import numpy as np
from pandas.core import nanops

# Scenario 1: values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64); 
# mask = np.zeros(4, dtype=bool); mask[na_pos] = True for na_pos in {0, 3}; 
# valid = np.flatnonzero(~mask); nanops.nanargmax/nanargmin/nanmax/nanmin(values, mask=mask)
values = np.array([2**63 + 1, 2**63 + 2, 2**63 + 3, 0], dtype=np.uint64)
mask = np.zeros(4, dtype=bool)
for na_pos in {0, 3}:
    mask[na_pos] = True
valid = np.flatnonzero(~mask)

try:
    result_nanargmax = nanops.nanargmax(values, mask=mask)
    probe("nanargmax with uint64 large values and mask", result_nanargmax)
except Exception as e:
    probe_exception("nanargmax with uint64 large values and mask", e)

try:
    result_nanargmin = nanops.nanargmin(values, mask=mask)
    probe("nanargmin with uint64 large values and mask", result_nanargmin)
except Exception as e:
    probe_exception("nanargmin with uint64 large values and mask", e)

try:
    result_nanmax = nanops.nanmax(values, mask=mask)
    probe("nanmax with uint64 large values and mask", result_nanmax)
except Exception as e:
    probe_exception("nanmax with uint64 large values and mask", e)

try:
    result_nanmin = nanops.nanmin(values, mask=mask)
    probe("nanmin with uint64 large values and mask", result_nanmin)
except Exception as e:
    probe_exception("nanmin with uint64 large values and mask", e)

# Scenario 2a: mask = np.array([True, False, False]); 
# values = np.full(3, np.iinfo(np.int64).min, dtype=np.int64) for nanargmax
mask2 = np.array([True, False, False])
values_nanargmax = np.full(3, np.iinfo(np.int64).min, dtype=np.int64)

try:
    result_nanargmax_int64 = nanops.nanargmax(values_nanargmax, mask=mask2)
    probe("nanargmax with int64.min values and mask [True, False, False]", result_nanargmax_int64)
except Exception as e:
    probe_exception("nanargmax with int64.min values and mask [True, False, False]", e)

# Scenario 2b: mask = np.array([True, False, False]); 
# values = np.full(3, np.iinfo(np.int64).max, dtype=np.int64) for nanargmin
values_nanargmin = np.full(3, np.iinfo(np.int64).max, dtype=np.int64)

try:
    result_nanargmin_int64 = nanops.nanargmin(values_nanargmin, mask=mask2)
    probe("nanargmin with int64.max values and mask [True, False, False]", result_nanargmin_int64)
except Exception as e:
    probe_exception("nanargmin with int64.max values and mask [True, False, False]", e)

